def hss(H, B, t):
    t = 0.93 * t
    I = (B * H**3 - (B - 2*t) * (H - 2*t)**3) / 12
    return dict(I=I, S=I / (H / 2), A=B*H - (B-2*t)*(H-2*t), t=t)

class Sub:
    def __init__(s, no, key, title):
        s.no, s.key, s.title = no, key, title
        s.code, s.loads, s.calcs, s.mat, s.welds, s.bolts, s.fixes, s.open, s.text = [], [], [], [], [], [], [], [], []
        SUBS.append(s)
    def c(s, cid, title, inputs, formula, demand, cap, unit, note="", fs=False):
        u = demand / cap if cap else 0.0
        s.calcs.append(dict(id=cid, title=title, inputs=inputs, formula=formula, demand=round(demand, 3), capacity=round(cap, 3),
                            unit=unit, util=round(u, 3), ok=u <= 1.0, note=note))
        return u

