def carry(s, prefixes, skip=(), skip_ids=()):
    """carry existing calc-notes rows (calcs.py) into this subsystem, unchanged, referenced by their C-ID"""
    for r in OLD["rows"]:
        if any(r["id"] == p or r["id"].startswith(p) and r["id"][len(p):].isalpha() for p in prefixes) and r["item"] not in skip and r["id"] not in skip_ids:
            s.calcs.append(dict(id=r["id"], title=r["item"], inputs=r["basis"], formula="see PF-CT_R2_calc_notes (calcs.py)", demand=r["demand"],
                                capacity=r["capacity"], unit=r["unit"], util=r["ratio"], ok=r["ok"], note=r["assume"], carried=True))

