def tie(name, kg, A, z):
    q = 0.613 * 44.7**2; F = q * 1.2 * A; Mo = F * z / 1000; Mr = 0.6 * kg * g * 0.4572
    T = max(Mo - Mr, 0) / 0.9144 / 2
    return F, Mo, Mr, T
